import Fade from "react-reveal/Fade";

function Piece(item) {
  function getImageFrame() {
    var pin = item.item;
    if (pin == null) {
      return "";
    }
    var rarity = pin.rarity;
    var setName = pin.setName == null ? "" : pin.setName;
    var isTokyo = setName.indexOf("Tokyo") !== -1;
    var image = "";

    if (rarity === "Common") {
      image =
        isTokyo === true
          ? "assets/images/frames/tokyo2020_common_frame.png"
          : "assets/images/frames/common_premiere.png";
    } else if (rarity === "Rare") {
      image =
        isTokyo === true
          ? "assets/images/frames/tokyo2020_rare_frame.png"
          : "assets/images/frames/rare_premiere.png";
    } else if (rarity === "Epic") {
      image =
        isTokyo === true
          ? "assets/images/frames/tokyo2020_epic_frame.png"
          : "assets/images/frames/epic_premiere.png";
    } else if (rarity === "Legendary") {
      image =
        isTokyo === true
          ? "assets/images/frames/tokyo2020_legendary_frame.png"
          : "assets/images/frames/legendary_premiere.png";
    }

    return image;
  }
  return (
    <>
      <Fade bottom duration={1000}>
        <a href="#">
          <article className="single-nft">
            <div className="single-nft__image-container">
              <img className="back-frame" src={getImageFrame()} />
              <img
                className="image-in-frame"
                src={item.item.imageURL}
                alt=""
              ></img>
            </div>
            <div className="single-nft__info">
              <h2 className="single-nft__name">{item.item.pinName}</h2>
              {/* <p className="single-nft__serial">#{item.item.serial_max}</p> */}
              {/* <p className="single-nft__price">
              {item.item.lowestAsk}
              <span className="single-nft__currency"> USDT</span>
            </p>
            <p className="single-pack__description">{item?.description}</p> */}
              {/*
            <p>{item.item.setName}</p>
            <p>
              {item.item.rarity} | {item.serial_max}
            </p>
            <p>{item.item.type}</p>
            <p>
              {" "}
              Listing count:
              {item.item.listingCount}
            </p>

            <div></div>
            <p>lowest ask</p>
            <span>${item.item.lowestAsk}</span>
            <span>usd</span>
            */}
            </div>
          </article>
        </a>
      </Fade>
    </>
  );
}

export default Piece;
