import React from "react";

export var YOUTUBE_TRAILER_ID = "hWPgC-QLWEo";

function YoutubeTrailer(props) {
  var className = props.className;
  var autoplay = props.autoplay === true;
  var query =
    autoplay === true
      ? "?autoplay=1&mute=1&loop=1&playlist=" +
        YOUTUBE_TRAILER_ID +
        "&controls=0&rel=0"
      : "?rel=0";
  var wrapperClass =
    className == null ? "youtube-trailer" : "youtube-trailer " + className;

  return (
    <div className={wrapperClass}>
      <iframe
        src={"https://www.youtube.com/embed/" + YOUTUBE_TRAILER_ID + query}
        title="Olympic Games Jam trailer"
        frameBorder="0"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
      />
    </div>
  );
}

export default YoutubeTrailer;
